/**
 * Generates a `*.module.d.css.ts` declaration next to every CSS Module in `src`.
 *
 * Without these files TypeScript falls back to the `vite/client` wildcard, which types every
 * module as `{ readonly [key: string]: string }`: a misspelled class name compiles, and with
 * `noUncheckedIndexedAccess` every class is `string | undefined`. `allowArbitraryExtensions`
 * makes TypeScript pick up the generated declarations instead.
 *
 * Class names come from Vite's own CSS pipeline (`preprocessCSS`), so they match the build.
 * The output is gitignored and regenerated by `npm run typecheck` and `npm run build`.
 */
import { readdir, readFile, writeFile } from 'node:fs/promises'
import { basename, join } from 'node:path'
import { preprocessCSS, resolveConfig } from 'vite'

const SOURCE_DIR = 'src'
const CSS_MODULE_SUFFIX = '.module.css'

const config = await resolveConfig({}, 'build')
const entries = await readdir(SOURCE_DIR, { recursive: true })
const cssModules = entries.filter((entry) => entry.endsWith(CSS_MODULE_SUFFIX)).toSorted()

for (const entry of cssModules) {
  const path = join(SOURCE_DIR, entry)
  const { modules } = await preprocessCSS(await readFile(path, 'utf8'), path, config)
  const classNames = Object.keys(modules ?? {}).toSorted()
  const properties = classNames.map((name) => `  readonly ${JSON.stringify(name)}: string\n`)
  const declaration =
    `// Generated by scripts/generate-css-module-types.ts from ${basename(path)}. Do not edit.\n` +
    `declare const styles: {\n${properties.join('')}}\n` +
    `export default styles\n`

  await writeFile(path.replace(/\.css$/, '.d.css.ts'), declaration)
}

console.log(`Generated types for ${cssModules.length} CSS Modules`)
